<?phpnamespace app\api\controller\market\recharge;use app\api\controller\Controller;use app\api\model\RechargePlan as RechargePlanModel;use app\api\model\Setting;/** * 用户充值套餐控制器 */class Plan extends Controller{    /**     * 列表     */    public function lists()    {		$setting =  Setting::getItem('recharge');        $model = new RechargePlanModel;        $plan = $model->getList(false);        return $this->renderSuccess(compact('plan','setting'));    }}